'use strict';
// Simplified educational power model. No thermal or dust transport model.
function incidenceFactor(sunAz,sunEl,panelAz,panelTilt){const r=Math.PI/180;return Math.max(0,Math.min(1,Math.sin(sunEl*r)*Math.cos(panelTilt*r)+Math.cos(sunEl*r)*Math.sin(panelTilt*r)*Math.cos((sunAz-panelAz)*r)));}
function solarBudget(samples,p){let stored=p.capacityWh*p.initialFraction,generatedWh=0,chargedWh=0,unservedWh=0,curtailedWh=0,minStoredWh=stored;const rows=[];for(const a of samples){const az=p.tracking?a.sun.az:p.azimuth,tilt=p.tracking?Math.max(0,Math.min(90,90-a.sun.el)):p.tilt,incidence=a.sv?incidenceFactor(a.sun.az,a.sun.el,az,tilt):0,powerW=p.irradiance*p.areaM2*p.efficiency*(1-p.lossFraction)*incidence,energy=powerW*p.stepHours,demand=p.loadW*p.stepHours;generatedWh+=energy;if(energy>=demand){const offered=(energy-demand)*p.chargeEfficiency,accepted=Math.min(p.capacityWh-stored,offered);stored+=accepted;chargedWh+=accepted;curtailedWh+=offered-accepted;}else{const deficit=demand-energy,taken=Math.min(stored,deficit);stored-=taken;unservedWh+=deficit-taken;}minStoredWh=Math.min(minStoredWh,stored);rows.push({powerW,storedWh:stored,incidence});}return{generatedWh,chargedWh,finalStoredWh:stored,minStoredWh,unservedWh,curtailedWh,rows};}
